import type { MetadataRoute } from "next";

/**
 * PWA web app manifest (served automatically at /manifest.webmanifest).
 * Icons are the ShopEase brand mark generated by scripts/build-brand-assets.ts.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "ShopEase — Everything You Love, All in One Place",
    short_name: "ShopEase",
    description:
      "Discover amazing products from verified sellers across India. Secure payments, easy returns, fast delivery.",
    id: "/",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#FAFAFC",
    theme_color: "#FF6B35",
    categories: ["shopping", "lifestyle"],
    icons: [
      { src: "/brand/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/brand/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/brand/icon-maskable-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
      { src: "/brand/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
